/**
 * Load a quiz for a route:
 * - /quiz/quiz-1, /quiz/quiz-2              -> built-in quizzes
 * - /quiz/new?topic=X[&focus=Y]             -> generated by Meta Muse
 * - /quiz/new?source=<id>[&focus=Y]         -> written from your document, every question quoted
 * The voice quiz uses the same hook, so any quiz can be taken out loud.
 */

import { useEffect, useState } from 'react';
import type { Quiz } from '@/lib/learning/quiz-generator';
import { BUILT_IN_QUIZZES } from '@/lib/mock/quizzes';
import { generateTopicQuiz } from '@/lib/learning/topic-quiz';
import { generateSourceQuiz, type SourceQuizStats } from '@/lib/learning/source-quiz';

export function useQuiz(quizId: string | undefined, topic: string | null, focus: string | null, source: string | null = null) {
  const [quiz, setQuiz] = useState<Quiz | null>(null);
  const [stats, setStats] = useState<SourceQuizStats | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setQuiz(null);
    setStats(null);
    setError(null);
    setLoading(true);

    const builtIn = quizId ? BUILT_IN_QUIZZES[quizId] : undefined;
    if (builtIn) {
      setQuiz(builtIn);
      setLoading(false);
      return;
    }

    const job =
      quizId === 'new' && source
        ? generateSourceQuiz(source, focus ?? undefined).then((q) => {
            if (!cancelled) setStats(q.stats);
            return q;
          })
        : quizId === 'new' && topic
          ? generateTopicQuiz(topic, focus ?? undefined)
          : null;

    if (job) {
      job
        .then((q) => !cancelled && setQuiz(q))
        .catch((e) => !cancelled && setError(e instanceof Error ? e.message : 'Quiz generation failed'))
        .finally(() => !cancelled && setLoading(false));
      return () => {
        cancelled = true;
      };
    }

    setError('This quiz does not exist.');
    setLoading(false);
  }, [quizId, topic, focus, source, attempt]);

  return { quiz, stats, error, loading, retry: () => setAttempt((a) => a + 1) };
}
